import { BaseController } from './BaseController';
import { Services } from '../services';

/** The new account's sign-in details, shown once after it is created. */
export interface CreatedAccount { username: string; email: string; password: string; emailed: boolean }

type State = { email: string; username: string; saving: boolean; error: string | null; created: CreatedAccount | null };

/**
 * Add a new account (principal/admin). The password is generated by the server
 * and emailed to the new user; it is also shown once here to hand over in case
 * the email doesn't arrive.
 */
export class AddUserController extends BaseController<State> {
  constructor(private readonly services: Services) {
    super({ email: '', username: '', saving: false, error: null, created: null });
  }

  set(patch: Partial<{ email: string; username: string }>) { this.setState({ ...patch, error: null }); }

  get canSubmit() {
    const s = this.state;
    return !s.saving && !!s.email.trim() && !!s.username.trim();
  }

  /** True once the account exists (the dialog then shows its sign-in details). */
  async submit(): Promise<boolean> {
    if (!this.canSubmit) return false;
    this.setState({ saving: true, error: null });
    try {
      const username = this.state.username.trim();
      const email = this.state.email.trim();
      const r = await this.services.personnel.create({ email, username, first_name: username, last_name: '', role: 'teacher' });
      this.setState({ created: { username, email, password: r.password, emailed: r.emailed } });
      return true;
    } catch (e) {
      this.setState({ error: BaseController.messageOf(e) });
      return false;
    } finally {
      this.setState({ saving: false });
    }
  }
}
